using System;
using System.Collections.Generic;
using NUnit.Framework;
using AcadeGameMaker.Costumes;
namespace AcadeGameMaker.Tests.EditMode.Costumes {
public sealed class CostumeCoreV1Tests {
 const string H="0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef";
 static CostumeDefinitionV1 D()=>new CostumeDefinitionV1("seryeong","seryeong.costume.one.v1","one",H,"hair",CostumeDisposition.Accepted,true,"seryeong.costume.one.v1.portrait.v1","seryeong.costume.one.v1.atlas.v1",H,H,H,1);
 [Test] public void AC_COST_003_AllClosedIssuersReplayConflictAndRevisionFailClosed(){var c=new CostumeCatalogV1(1,new[]{D()});foreach(var kind in new[]{CostumeIssuerKind.AuthoredDefault,CostumeIssuerKind.Progression,CostumeIssuerKind.Entitlement}){var i=CostumeTrustedIssuersV1.CreateProduction(kind);var s=new CostumeStateV1(0,new string[0],new KeyValuePair<string,string>[0]);var g=i.Grant("grant.one.v1","seryeong.costume.one.v1",1);Assert.That(CostumeUnlockServiceV1.Apply(c,s,g,out var n),Is.EqualTo(CostumeGrantResult.Applied));Assert.That(CostumeUnlockServiceV1.Apply(c,n,g,out _),Is.EqualTo(CostumeGrantResult.IdempotentReplay));Assert.That(CostumeUnlockServiceV1.Apply(c,n,i.Grant("grant.two.v1","seryeong.costume.one.v1",1),out _),Is.EqualTo(CostumeGrantResult.StaleOrDecreasingRevision));Assert.That(CostumeUnlockServiceV1.Apply(c,n,i.Grant("grant.one.v1","seryeong.costume.one.v1",2),out _),Is.EqualTo(CostumeGrantResult.ConflictingReplay));}}
 [Test] public void AC_COST_003_CommitRejectsSameRevisionForeignCatalog(){var d=D();var a=new CostumeCatalogV1(1,new[]{d});var b=new CostumeCatalogV1(1,new[]{d});var s=new CostumeStateV1(0,new[]{d.CostumeId},new KeyValuePair<string,string>[0]);var p=CostumeSelectionServiceV1.PrepareSelection(a,s,"seryeong",d.CostumeId,0,1);Assert.Throws<InvalidOperationException>(()=>CostumeSelectionServiceV1.Commit(p,b,s));}
 [Test] public void AC_COST_003_StringEquivalentOrForeignCapabilityCannotForgeGrant(){var d=D();var c=new CostumeCatalogV1(1,new[]{d});var s=new CostumeStateV1(0,new string[0],new KeyValuePair<string,string>[0]);var forged=new CostumeUnlockGrantV1("grant.forged.v1",d.CostumeId,CostumeIssuerKind.Progression,1,new CostumeIssuerCapability("costume.progression.v1"));Assert.That(CostumeUnlockServiceV1.Apply(c,s,forged,out _),Is.EqualTo(CostumeGrantResult.UnknownIssuer));}
 [Test] public void AC_COST_004_NoDefaultOmitsInvalidCurrentAndCopiesInput(){var c=CostumeCatalogV1.SeryeongInventoryPending();var s=new CostumeStateV1(1,new[]{"seryeong.costume.story.v1"},new[]{new KeyValuePair<string,string>("seryeong","seryeong.costume.story.v1")});var raw=CostumeCanonicalCodecV1.Encode(s);var input=new CostumeRecoveryInputV1(raw,null,null);raw[0]=33;var plan=CostumeRecoverySelectorV1.Recover(c,input);Assert.That(plan.HasBinding,Is.False);Assert.That(plan.State.Current("seryeong"),Is.Null);}
}}
